def agent_memory(max_context, vector_store):
    class Memory:
        def __init__(self):
            self.history = []
            self.summary = ""
        def add_message(self, role, text):
            self.history.append({"role": role, "content": text})
            if len(self.history) > max_context:
                oldest = self.history.pop(0)
                self.summary += f"\n{oldest['role']}: {oldest['content']}"
                vector_store.add(self.summary)
        def get_context(self, query):
            relevant = vector_store.search(query, top_k=3)
            recent = self.history[-max_context:]
            context = f"Summary: {self.summary}\n\nRecent:\n"
            for msg in recent:
                context += f"{msg['role']}: {msg['content']}\n"
            return context
    return Memory()
